sys_ui_action.script:
function confirmDeleteSelectedWorkloads() {
    var checkedSysIds = g_list.getChecked();

    // Every message this action shows goes through here.
    //
    // The list has no g_form, so the form action's g_form.addInfoMessage/addErrorMessage is not
    // available. This used to write into top.document's `output_messages` / `page_notifications`
    // div, guarded by `if (container)` -- and on the list those elements are not present, so the
    // guard swallowed the message and the action looked like it had done nothing. That is what
    // hid the "another job is already running" refusal: the server was returning it correctly,
    // and the client was dropping it on the floor. The modal below is the same one the selection
    // and validation errors already use, which is why those two were the ones that did show.
    function showNotice(title, message) {
        var gm = new GlideModal('', false, 500);
        gm.setTitle(title);

        top.window.deleteSelectedWorkloadsCallback = function() {
            gm.destroy();
            return false;
        };

        gm.renderWithContent(
            '<div style="padding: 8px 4px 4px 4px; font-size: 16px; line-height: 1.5;">' +
                '<p>' + message + '</p>' +
                '<div style="display:flex; justify-content:flex-end; margin-top:20px;">' +
                    '<button style="width: 100%" class="btn btn-default" ' +
                        'onclick="top.window.deleteSelectedWorkloadsCallback(); return false;">' +
                        'OK</button>' +
                '</div>' +
            '</div>');
    }

    if (!checkedSysIds) {
        showNotice('No workloads selected',
            'No workloads selected. Please select one or more workloads from the list.');
        return false;
    }

    var validateGa = new GlideAjax('IllumioDeletionHandler');
    validateGa.addParam('sysparm_name', 'validateWorkloadsForDeletion');
    validateGa.addParam('sysparm_checked_sysids', checkedSysIds);
    validateGa.getXMLAnswer(function(response) {
        if (!response) return;

        var validation = JSON.parse(response);
        var validCount = validation.managedCount + validation.unmanagedCount;

        if (validation.unknownCount > 0) {
            showNotice('No workloads selected',
                'One or more invalid workloads selected. Please run this action on existing ' +
                'Managed or Unmanaged workloads.');
            return;
        }

        var gmConfirm = new GlideModal('', false, 700);
        gmConfirm.setTitle('Confirm selected workload deletion');

        top.window.deleteSelectedWorkloadsCallback = function(answer) {
            gmConfirm.destroy();

            if (answer === 'yes') {
                var ga = new GlideAjax('IllumioDeletionHandler');
                ga.addParam('sysparm_name', 'deleteSelectedWorkloads');
                ga.addParam('sysparm_checked_sysids', checkedSysIds);
                ga.getXMLAnswer(function(deleteResponse) {
                    var result = JSON.parse(deleteResponse);
                    if (result.success) {
                        g_list.refresh();
                        showNotice('Deletion started', result.message);
                    } else {
                        // Refusals land here: another job already running, workloads spanning
                        // more than one PCE Configuration, nothing eligible, or a failure to
                        // write the payload rows. All of them are things the user has to read.
                        showNotice('Deletion not started', result.message);
                    }
                });
            }

            return false;
        };

        var html =
            '<div style="padding: 8px 4px 4px 4px; font-size: 16px; line-height: 1.5;">' +
                '<p>You are about to delete <b>' + validCount + '</b> selected workload(s) from PCE.</p>' +
                '<ul style="margin: 10px 0;">' +
                    '<li><b>Managed</b> workloads (with VEN) will be <b>unpaired</b> from PCE.</li>' +
                    '<li><b>Unmanaged</b> workloads will be <b>deleted</b> from PCE.</li>' +
                '</ul>' +
                '<p>It is strongly recommended to run the following in order before proceeding:<br>' +
                '1. Data Collection - To discover the latest state workloads.<br>' +
                '2. Preview workload deletion - To verify all workloads.</p>' +
                '<p><b>Deletion is a non-reversible action.</b> Click "Yes" to proceed.</p>' +
                '<div style="display:flex; justify-content:flex-end; gap:12px; margin-top:20px;">' +
                    '<button style="flex: 1; width: 100%" class="btn btn-default" onclick="top.window.deleteSelectedWorkloadsCallback(\'no\'); return false;">Cancel</button>' +
                    '<button style="flex: 1; width: 100%" class="btn btn-danger" onclick="top.window.deleteSelectedWorkloadsCallback(\'yes\'); return false;">Yes</button>' +
                '</div>' +
            '</div>';

        gmConfirm.renderWithContent(html);
    });

    return false;
}
